import math
import numpy as np
def _surface(v0, wb, m, om, ci, c0, sg):
    return np.array([v0, math.sqrt(2.0 * v0 / m) / wb, m, om, ci, c0, sg])
def _beads(n, shift, amp, a):
    x = shift + a * np.arcsinh(amp * np.sin(2.0 * np.pi * (np.arange(n) + 0.3) / n))
    return np.column_stack([x, np.zeros(n)])
def _digest(v):
    return np.asarray(v, dtype=float)
assert np.allclose(_digest(assemble_action_derivatives(_beads(8, 0.0, 3.0, 0.62), _surface(0.011, 0.0058, 1836.0, 0.0031, 0.015, 0.08, 0.4), 3000.0, 1500.0, 0)), target)

